// SSAPropagationCallGraphBuilder.java:1238-1277
public void visitNew(SSANewInstruction instruction) {
  InstanceKey iKey = getInstanceKeyForAllocation(instruction.getNewSite());
  if (iKey == null) { return; }
  PointerKey def = getPointerKeyForLocal(instruction.getDef());
  IClass klass = iKey.getConcreteType();
  if (klass == null) { return; }

  // Create constraint for pointer analysis
  if (!contentsAreInvariant(symbolTable, du, instruction.getDef())) {
    system.newConstraint(def, iKey);
  }

  // side effect of new: may call class initializer
  processClassInitializer(klass);  // Handles <clinit>, but NOT ClassLoader.loadClass
  processFinalizeMethod(klass);
  // ... rest of method
}

// ClassFactoryContextSelector.java:64-72
public static boolean isClassFactory(MethodReference m) {
  if (m.equals(FOR_NAME_REF)) { return true; }      // Only explicit Class.forName
  if (m.equals(LOAD_CLASS_REF)) { return true; }    // Only explicit ClassLoader.loadClass
  return false;
  // Does not recognize implicit JVM class loading from 'new' bytecode
}
